 await db.exec('reset role');const contratos=await one('select private.perfis_atendimento()');
 for(const perfil of ['autocenter','troca_oleo'])assert.deepEqual(Object.keys(contratos[perfil].campos).sort(),perfisAtendimento[perfil].grupos.flatMap(g=>g.campos.map(c=>c.id)).sort());
