 const prever=(f=foleo)=>one('select private.previsao_troca_oleo($1,$2,$3)',[f,'2026-10-20',null]);
 assert.equal((await prever()).data_prevista,'2027-01-28');
 assert.equal(await prever({...foleo,campos:{...foleo.campos,km_por_dia:''}}),null,'Sem uso ou data, não inventa previsão');
 assert.equal((await prever({...foleo,campos:{...foleo.campos,proxima_data:'2026-11-01'}})).data_prevista,'2026-11-01');
 assert.equal(await prever({...foleo,campos:{...foleo.campos,proxima_km:'80000'}}),null);
 await db.exec('set role authenticated');
 const wo=await one("select public.configurar_nova_empresa($1,'Troca de óleo QA','','{}','automotivo','troca_oleo')",[uuid()]);
 await db.exec(`reset role;update public.assinaturas_oficina set codigo_plano='complete' where oficina_id='${wo}';set role authenticated;`);
