 const vo=await one("select public.cadastrar_veiculo_orcamento($1,$2,'Veículo QA','QAQ1A23')",[wo,co.id]);
 await db.exec('reset role');
 const os=uuid();
 // Fixture de OS concluída: os gatilhos reais calculam a fila.
 await db.query("insert into public.ordens_servico(id,oficina_id,cliente_id,veiculo_id,numero,situacao,data_servico,ficha_especialidade,criado_por) values($1,$2,$3,$4,999,'ready',current_date-100,$5,$6)",[os,wo,co.id,vo,foleo,u]);
 assert.equal(await one('select count(*)::int from public.recontatos_oleo where ordem_servico_id=$1',[os]),1);
