 assert.equal((await one('select public.consultar_recontatos_oleo($1)',[wo])).length,1);
 await assert.rejects(()=>one('select public.reservar_recontato_oleo()'),e=>e.code==='42501');
 await db.exec('reset role;set role service_role');
 const tarefa=await one('select public.reservar_recontato_oleo()');assert.equal(tarefa.id,os);assert.ok(!JSON.stringify(tarefa).includes('Cliente de óleo'));
 assert.equal(await one('select public.reservar_recontato_oleo()'),null,'Reserva impede processamento duplicado');
 await one('select public.concluir_recontato_oleo($1,$2,$3,$4)',[os,uuid(),'Resposta antiga deve ser ignorada','teste']);
