 await db.exec('set role service_role');await one('select public.concluir_recontato_oleo($1,$2,$3,$4)',[os,tarefa.tentativa,'Qual a quilometragem atual? Podemos combinar sua revisão?','teste']);
 await db.exec('reset role;set role authenticated');
 assert.equal((await one('select public.consultar_recontatos_oleo($1)',[wo]))[0].situacao,'sugerido');
 await one('select public.encerrar_recontato_oleo($1,$2,true)',[wo,os]);
 assert.equal((await one('select public.consultar_recontatos_oleo($1)',[wo])).length,0);
