 await assert.rejects(()=>one('select public.consultar_recontatos_oleo($1)',[wo]),e=>e.code==='42501');
 console.log('PASS previsão de óleo, dados insuficientes, data antecipada, fila idempotente, IA sem identidade, respostas antigas e isolamento.');
 console.log('PASS criação atômica, rollback, idempotência, orçamento, painel, comissão, deslocamento, fotos e isolamento entre empresas.');
